<script setup lang="ts">
import {computed,ref} from 'vue'
import {useI18n} from 'vue-i18n'
import type {MeasurementCoverage} from '../types'
const props=defineProps<{coverage:MeasurementCoverage}>()
const {t}=useI18n();const mission=ref('moon')
const groups=computed(()=>Object.entries(props.coverage.features.filter(f=>f.mission===mission.value).reduce<Record<string,typeof props.coverage.features>>((groups,f)=>{(groups[f.task_id]??=[]).push(f);return groups},{})))
</script>
<template><section class="section task-data-matrix"><div class="section-heading"><div><span class="eyebrow">{{t('observedOnly')}}</span><h2>{{t('taskDatasetPairs')}}</h2></div><select v-model="mission" :aria-label="t('chooseMission')"><option value="moon">{{t('moon')}}</option><option value="mars">{{t('mars')}}</option></select></div><p class="notice">{{t('pairingIntro')}}</p><div v-for="[task,features] in groups" :key="task" class="panel"><h3>{{task}} / {{t('task_'+task)}}</h3><div class="table-scroll"><table><thead><tr><th>{{t('features')}}</th><th>{{t('planetData')}}</th><th>{{t('earthData')}}</th><th>{{t('status')}}</th></tr></thead><tbody><tr v-for="feature in features" :key="feature.feature_id"><th>{{feature.name}}<small class="coordinate-caption">{{feature.feature_id}}</small></th><td><a v-for="product in feature.planet_products" :key="product.url" :href="product.url" target="_blank" rel="noopener" class="source-link">{{product.title}} ↗</a><template v-if="!feature.planet_products.length"><a v-for="source in feature.planet_sources" :key="source.name" :href="source.url||undefined" target="_blank" rel="noopener" class="source-link">{{source.name}} ↗</a></template></td><td><a v-for="product in feature.earth_products.slice(0,4)" :key="product.url" :href="product.url" target="_blank" rel="noopener" class="source-link">{{product.title}} ↗</a><template v-if="!feature.earth_products.length"><a v-for="source in feature.earth_sources" :key="source.name" :href="source.url||undefined" target="_blank" rel="noopener" class="source-link">{{source.name}} ↗</a></template></td><td><span class="badge">{{t('pair_'+feature.status)}}</span><p class="small">{{feature.reason}}</p><router-link v-for="site in feature.ready_sites" :key="site" :to="{path:'/'+mission,query:{site,tasks:feature.task_id,step:3}}" class="source-link">{{t('openComparison')}} ↗</router-link></td></tr></tbody></table></div></div><a href="/api/measurements/products" target="_blank" rel="noopener" class="source-link">{{t('fullProvenance')}} ↗</a></section></template>
